<template><div class="discipline-page">
  <h1>红黄牌与停赛管理</h1><p>按球队独立累计。个人服满后只清触发停赛的牌种；两黄变红只计红牌，同时触发时执行较长停赛。</p>
  <div class="filters"><label>赛季<select aria-label="赛季" v-model="seasonId" :disabled="busy"><option value="">请选择赛季</option><option v-for="s in seasons" :key="s.id" :value="s.id">{{ s.season_name }}</option></select></label>
    <label>赛事<select aria-label="赛事" v-model="competitionId" :disabled="busy"><option value="">请选择赛事</option><option v-for="c in competitions" :key="c.id" :value="c.id">{{ c.league_type }}</option></select></label><button :disabled="busy||!competitionId" @click="load">刷新统计</button><RouterLink to="/admin-seasons">添加赛事／设置规则</RouterLink></div>
  <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="success" role="status">{{ success }}</p>
  <template v-if="data"><p v-if="!data.configured" class="error">请先补全本赛事的停赛规则。</p>
    <p v-else>黄牌累计 {{ data.competition.yellow_threshold }} 张停 {{ data.competition.yellow_suspension }} 场；红牌累计 {{ data.competition.red_threshold }} 张停 {{ data.competition.red_suspension }} 场。</p>
    <div v-if="data.warnings.length" class="warning"><strong>待核对的停赛执行</strong><p v-for="(v,i) in data.warnings" :key="i">比赛 #{{ v.schedule_id }}：{{ v.message }}</p></div>
    <p v-if="!data.groups.length">本赛事暂无球队。</p>
    <section v-for="team in data.groups" :key="team.id" class="team-card"><h2>{{ team.team_name }}</h2><div class="table-wrap"><table><thead><tr><th>球员</th><th>号码</th><th>累计黄牌</th><th>累计红牌</th><th>历史黄／红</th><th>剩余停赛</th><th>明细／纠正</th></tr></thead><tbody>
      <tr v-for="p in team.players" :key="p.key"><td>{{ p.player_name }}<small v-if="!p.current_member">（历史名单）</small><small v-if="!p.player_id">（旧名单身份）</small></td><td>{{ p.jersey_number }}</td><td>{{ p.yellow }}</td><td>{{ p.red }}</td><td>{{ p.total_yellow }}／{{ p.total_red }}</td><td><strong>{{ p.remaining }} 场</strong></td><td><button @click="detail=p">查看明细</button> <button v-if="p.origin||data.warnings.some(w=>w.key===p.key)" :disabled="busy" @click="adjust={key:p.key,name:p.player_name,remaining:p.remaining,reason:''};resetOpen=false">纠正停赛</button></td></tr>
      <tr v-if="!team.players.length"><td colspan="7">暂无球员</td></tr>
    </tbody></table></div></section>
    <section v-if="detail" class="team-card"><h2>{{ detail.player_name }}的纪律明细</h2><button @click="detail=null">关闭明细</button><p v-if="!detail.records.length">暂无红黄牌或停赛记录</p><p v-for="(r,i) in detail.records" :key="i">{{ recordText(r) }} <RouterLink v-if="r.schedule_id" :to="`/admin-schedule/${r.schedule_id}/report`">查看比赛 #{{ r.schedule_id }}</RouterLink></p></section>
    <form v-if="adjust" class="team-card" @submit.prevent="saveAdjust"><h2>纠正 {{ adjust.name }} 的剩余停赛</h2><p>设为0视为服满，只清触发本次停赛的牌种。操作保留记录。</p><label>剩余停赛场数<input v-model.number="adjust.remaining" type="number" min="0" max="100" required></label><label>纠正原因<textarea v-model="adjust.reason" maxlength="500" required></textarea></label><button :disabled="busy">确认纠正</button><button type="button" :disabled="busy" @click="adjust=null">取消</button></form>
    <button class="danger" :disabled="busy" @click="resetOpen=true;adjust=null;resetReason='';confirmName=''">累计红黄牌全部清零</button>
    <form v-if="resetOpen" class="team-card warning" @submit.prevent="reset"><h2>清零 {{ data.competition.league_type }}</h2><p>影响本赛事全部 {{ data.groups.length }} 支球队，解除 {{ suspendedCount }} 人的未完成停赛。原报告和历史记录保留；清零前比赛的补报不进入新阶段。</p><label>阶段说明／清零原因<textarea v-model="resetReason" maxlength="500" required></textarea></label><label>输入完整赛事名称确认<input v-model="confirmName" required autocomplete="off"></label><button class="danger" :disabled="busy||confirmName!==data.competition.league_type">确认全部清零并解除停赛</button><button type="button" :disabled="busy" @click="resetOpen=false">取消</button></form>
    <details class="team-card"><summary>清零与纠正记录</summary><p v-if="!data.operations.length">暂无操作</p><p v-for="o in [...data.operations].reverse()" :key="o.id">{{ o.operation==='reset'?'赛事全部清零':'纠正停赛' }} · {{ o.created_at }} · 管理员 #{{ o.actor_admin_id }} · {{ o.reason }}</p></details>
  </template>
</div></template>
<script setup>
import {ref,computed,watch,onMounted} from 'vue'
import api from '../api/http'
const seasons=ref([]),seasonId=ref(''),competitions=ref([]),competitionId=ref(''),data=ref(null),error=ref(''),success=ref(''),busy=ref(false),detail=ref(null),adjust=ref(null),resetOpen=ref(false),resetReason=ref(''),confirmName=ref('');let sequence=0,competitionSequence=0
const suspendedCount=computed(()=>data.value?.groups.flatMap(g=>g.players).filter(p=>p.remaining>0).length||0)
const fail=e=>error.value=e.response?.data?.message||'操作失败，请刷新后重试'
watch(seasonId,async id=>{const n=++competitionSequence;competitionId.value='';competitions.value=[];if(!id)return;try{const r=await api.get('/competitions',{params:{season_id:id}});if(n===competitionSequence)competitions.value=r.data.competitions}catch(e){if(n===competitionSequence)fail(e)}})
watch(competitionId,()=>{data.value=null;detail.value=null;adjust.value=null;resetOpen.value=false;success.value='';load()})
async function load(){const n=++sequence;data.value=null;detail.value=null;adjust.value=null;resetOpen.value=false;if(!competitionId.value)return;error.value='';try{const r=await api.get(`/competitions/${competitionId.value}/discipline`);if(n===sequence)data.value=r.data}catch(e){if(n===sequence)fail(e)}}
async function mutate(operation,body){busy.value=true;++sequence;error.value='';success.value='';const id=competitionId.value;try{const r=await api.post(`/competitions/${id}/discipline/${operation}`,body,{headers:{'If-Match':String(data.value.revision)}});if(id===competitionId.value){data.value=r.data;adjust.value=null;detail.value=null;resetOpen.value=false;success.value='操作已完成并记录。'}}catch(e){fail(e)}finally{busy.value=false}}
const saveAdjust=()=>mutate('adjust',{key:adjust.value.key,remaining:adjust.value.remaining,reason:adjust.value.reason})
const reset=()=>mutate('reset',{reason:resetReason.value,confirm_name:confirmName.value})
function recordText(r){if(r.operation==='card')return `${r.card_type==='yellow'?'黄牌':'红牌'}${r.excluded?'（属于清零前阶段）':''}`;if(r.operation==='suspension')return `触发停赛 ${r.remaining} 场`;if(r.operation==='served')return `执行停赛，剩余 ${r.remaining} 场`;if(r.operation==='reset')return `赛事清零：${r.reason}`;return `管理员纠正为 ${r.remaining} 场：${r.reason}`}
onMounted(async()=>{try{seasons.value=(await api.get('/season')).data;seasonId.value=seasons.value.find(s=>s.is_active)?.id||seasons.value[0]?.id||''}catch(e){fail(e)}})
</script>
<style scoped>.discipline-page{max-width:1200px;margin:auto;padding:24px}.discipline-page p{line-height:1.8;margin:12px 0}.filters{display:flex;align-items:end;gap:16px;flex-wrap:wrap}.discipline-page label{display:block;margin:12px 0}.discipline-page input,.discipline-page select,.discipline-page textarea{display:block;padding:10px;max-width:100%;border:1px solid #c5d3e1;border-radius:6px;font:inherit}.discipline-page button{padding:9px 12px;margin:4px;border:1px solid #bdcee0;border-radius:6px;background:white;color:#235a87;cursor:pointer}.discipline-page button:disabled{opacity:.5;cursor:default}.team-card{background:white;border:1px solid #d4e0eb;border-radius:12px;padding:20px;margin:20px 0}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:680px}td,th{text-align:left;padding:12px;border-bottom:1px solid #e1e9f0}.warning{background:#fff7e6;padding:16px}.error,.discipline-page .danger{color:#aa2535}.discipline-page small{display:block;color:#60758a}@media(max-width:600px){.discipline-page{padding:12px}.team-card{padding:12px}}</style>
